import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String nLine = br.readLine();
        int n = Integer.parseInt(nLine);
        String sLine = br.readLine();
        char[] s = sLine.toCharArray();
        int[] counts = new int[3];
        int[][] positions = new int[3][n];
        for (int i = 0; i < n; i++) {
            int type = s[i] == 'K' ? 0 : (s[i] == 'V' ? 1 : 2);
            positions[type][counts[type]] = i;
            counts[type]++;
        }
        int[][][][] dp = new int[2][counts[0] + 1][counts[1] + 1][counts[2] + 1];
        for (int[][][] layer : dp) for (int[][] row : layer) for (int[] col : row) Arrays.fill(col, Integer.MAX_VALUE / 2);
        dp[0][0][0][0] = 0;
        for (int a = 0; a <= counts[0]; a++)
            for (int b = 0; b <= counts[1]; b++)
                for (int c = 0; c <= counts[2]; c++)
                    for (int lastFlag = 0; lastFlag < 2; lastFlag++) {
                        int currentCost = dp[lastFlag][a][b][c];
                        if (currentCost >= Integer.MAX_VALUE / 2) continue;
                        if (a < counts[0] && lastFlag == 0) {
                            int swaps = 0, posA = positions[0][a];
                            for (int i = b; i < counts[1]; i++) if (positions[1][i] < posA) swaps++;
                            for (int i = c; i < counts[2]; i++) if (positions[2][i] < posA) swaps++;
                            dp[0][a + 1][b][c] = Math.min(dp[0][a + 1][b][c], currentCost + swaps);
                        }
                        if (b < counts[1]) {
                            int swaps = 0, posB = positions[1][b];
                            for (int i = a; i < counts[0]; i++) if (positions[0][i] < posB) swaps++;
                            for (int i = c; i < counts[2]; i++) if (positions[2][i] < posB) swaps++;
                            dp[1][a][b + 1][c] = Math.min(dp[1][a][b + 1][c], currentCost + swaps);
                        }
                        if (c < counts[2]) {
                            int swaps = 0, posC = positions[2][c];
                            for (int i = a; i < counts[0]; i++) if (positions[0][i] < posC) swaps++;
                            for (int i = b; i < counts[1]; i++) if (positions[1][i] < posC) swaps++;
                            dp[0][a][b][c + 1] = Math.min(dp[0][a][b][c + 1], currentCost + swaps);
                        }
                    }
        int answer = Math.min(dp[0][counts[0]][counts[1]][counts[2]], dp[1][counts[0]][counts[1]][counts[2]]);
        System.out.println(answer);
    }
}
